s=json.loads("\"diff --git a/src/extension/commands/open-editor.ts b/src/extension/commands/open-editor.ts\\nindex b1b4678..b89318e 100644\\n--- a/src/extension/commands/open-editor.ts\\n+++ b/src/extension/commands/open-editor.ts\\n@@ -33,6 +33,7 @@ import {\\n } from '../services/mcp-server-config-writer';\\n import { SlackApiService } from '../services/slack-api-service';\\n import { executeSlashCommandInTerminal } from '../services/terminal-execution-service';\\n+import { CommentaryAiService } from '../services/commentary-ai-service';\\n import { listCopilotModels } from '../services/vscode-lm-service';\\n import { AnthropicApiKeyManager } from '../utils/anthropic-api-key-manager';\\n import { countUnreadVersions, extractVersions, parseChangelog } from '../utils/changelog-parser';\\n@@ -100,6 +101,8 @@ import {\\n \\n // Module-level variables to share state between commands\\n let currentPanel: vscode.WebviewPanel | undefined;\\n+let activeCommentary: CommentaryAiService | undefined;\\n+let commentaryTerminal: vscode.Terminal | undefined;\\n let fileService: FileService;\\n let slackTokenManager: SlackTokenManager;\\n let slackApiService: SlackApiService;\\n@@ -426,12 +429,28 @@ export function registerOpenEditorCommand(\\n                     // Non-fatal: continue with run even if MCP auto-start fails\\n                   }\\n \\n-                  // Run the slash command in terminal\\n+                  // Stop the previous observer before starting a new execution.\\n+                  activeCommentary?.stop();\\n+                  activeCommentary = undefined;\\n                   const result = executeSlashCommandInTerminal({\\n                     workflowName: message.payload.workflow.name,\\n                     workingDirectory: workspacePath,\\n                   });\\n \\n+                  if (message.payload.commentaryEnabled && result.sessionId) {\\n+                    const observer = new CommentaryAiService(\\n+                      message.payload.workflow, workspacePath, result.sessionId,\\n+                      (text) => { void webview.postMessage({ type: 'POST_COMMENTARY', payload: { text } }); }\\n+                    );\\n+                    activeCommentary = observer;\\n+                    commentaryTerminal = result.terminal;\\n+                    void observer.start().catch((error) => {\\n+                      void webview.postMessage({ type: 'POST_COMMENTARY', payload: {\\n+                        text: `Commentary watcher could not start: ${String(error)}`,\\n+                      } });\\n+                    });\\n+                  }\\n+\\n                   // Send success response\\n                   webview.postMessage({\\n                     type: 'RUN_AS_SLASH_COMMAND_SUCCESS',\\n@@ -2007,8 +2026,17 @@ export function registerOpenEditorCommand(\\n       );\\n \\n       // Handle panel disposal\\n+      context.subscriptions.push(vscode.window.onDidCloseTerminal((terminal) => {\\n+        if (terminal === commentaryTerminal) {\\n+          activeCommentary?.stop();\\n+          activeCommentary = undefined;\\n+          commentaryTerminal = undefined;\\n+        }\\n+      }));\\n       currentPanel.onDidDispose(\\n         () => {\\n+          activeCommentary?.stop();\\n+          activeCommentary = undefined;\\n           // Cancel any ongoing OAuth polling when panel is closed\\n           if (activeOAuthService) {\\n             activeOAuthService.cancelPolling();\\ndiff --git a/src/extension/services/commentary-ai-service.ts b/src/extension/services/commentary-ai-service.ts\\nnew file mode 100644\\nindex 0000000..46bc121\\n--- /dev/null\\n+++ b/src/extension/services/commentary-ai-service.ts\\n@@ -0,0 +1,82 @@\\n+/** An independent Claude CLI session used exclusively for observation. */\\n+import { spawn } from 'node:child_process';\\n+import type { Workflow } from '../../shared/types/messages';\\n+import { JsonlWatcherService, transcriptPath } from './jsonl-watcher-service';\\n+\\n+export class CommentaryAiService {\\n+  private watcher?: JsonlWatcherService;\\n+  private commentarySessionId?: string;\\n+  private queue: string[] = [];\\n+  private processing = false;\\n+  private stopped = false;\\n+  private flushTimer?: NodeJS.Timeout;\\n+  private activeProcess?: ReturnType<typeof spawn>;\\n+\\n+  constructor(\\n+    private readonly workflow: Workflow,\\n+    private readonly cwd: string,\\n+    private readonly sessionId: string,\\n+    private readonly emit: (text: string) => void\\n+  ) {}\\n+\\n+  async start(): Promise<void> {\\n+    this.watcher = new JsonlWatcherService(transcriptPath(this.cwd, this.sessionId), (events) => {\\n+      this.queue.push(...events);\\n+      void this.process();\\n+    });\\n+    await this.watcher.start();\\n+    this.flushTimer = setInterval(() => { this.watcher?.flush(); }, 4000);\\n+    this.emit('Observing workflow execution…');\\n+  }\\n+\\n+  private async process(): Promise<void> {\\n+    if (this.processing || this.stopped || !this.queue.length) return;\\n+    this.processing = true;\\n+    try {\\n+      while (!this.stopped && this.queue.length) {\\n+        const events = this.queue.splice(0, 25);\\n+        const first = !this.commentarySessionId;\\n+        const prompt = first\\n+          ? `You are an independent observer of a running Claude Code workflow. Explain the events clearly and briefly, highlight errors, retries, and progress. Do not give commands or attempt to control execution. Workflow definition: ${JSON.stringify(this.workflow)}\\\\nRecent transcript events:\\\\n${events.join('\\\\n')}`\\n+          : `Describe significant progress, failures, or repeated attempts since the last update. Avoid repetition. New transcript events:\\\\n${events.join('\\\\n')}`;\\n+        const result = await this.invoke(prompt);\\n+        if (this.stopped) break;\\n+        if (typeof result.session_id === 'string' && result.session_id) this.commentarySessionId = result.session_id;\\n+        if (typeof result.result === 'string' && result.result.trim()) this.emit(result.result.trim());\\n+      }\\n+    } catch (error) {\\n+      if (!this.stopped) this.emit(`Commentary unavailable: ${error instanceof Error ? error.message : String(error)}`);\\n+    } finally {\\n+      this.processing = false;\\n+      if (!this.stopped && this.queue.length) void this.process();\\n+    }\\n+  }\\n+\\n+  private invoke(prompt: string): Promise<{ result?: string; session_id?: string }> {\\n+    return new Promise((resolve, reject) => {\\n+      const args = ['-p', '--model', 'haiku', '--output-format', 'json'];\\n+      if (this.commentarySessionId) args.push('--resume', this.commentarySessionId);\\n+      const proc = spawn('claude', args, { cwd: this.cwd, stdio: ['pipe', 'pipe', 'pipe'] });\\n+      this.activeProcess = proc;\\n+      let output = '';\\n+      let stderr = '';\\n+      proc.stdout.on('data', (chunk: Buffer) => { output += chunk.toString(); });\\n+      proc.stderr.on('data', (chunk: Buffer) => { stderr += chunk.toString(); });\\n+      proc.on('error', reject);\\n+      proc.on('close', (code) => {\\n+        if (this.activeProcess === proc) this.activeProcess = undefined;\\n+        if (code !== 0) { reject(new Error(stderr.trim() || `Claude exited ${code}`)); return; }\\n+        try { resolve(JSON.parse(output)); } catch { reject(new Error('Invalid commentary JSON response')); }\\n+      });\\n+      proc.stdin.end(prompt);\\n+    });\\n+  }\\n+\\n+  stop(): void {\\n+    this.stopped = true;\\n+    this.watcher?.stop();\\n+    if (this.flushTimer) clearInterval(this.flushTimer);\\n+    this.queue = [];\\n+    this.activeProcess?.kill();\\n+  }\\n+}\\ndiff --git a/src/extension/services/jsonl-watcher-service.ts b/src/extension/services/jsonl-watcher-service.ts\\nnew file mode 100644\\nindex 0000000..437d972\\n--- /dev/null\\n+++ b/src/extension/services/jsonl-watcher-service.ts\\n@@ -0,0 +1,87 @@\\n+/** Incremental Claude transcript reader. The watcher never changes the execution session. */\\n+import { watch, type FSWatcher, promises as fs } from 'node:fs';\\n+import os from 'node:os';\\n+import path from 'node:path';\\n+\\n+export function transcriptPath(cwd: string, sessionId: string): string {\\n+  const encoded = path.resolve(cwd).replace(/[^a-zA-Z0-9-]/g, '-');\\n+  return path.join(os.homedir(), '.claude', 'projects', encoded, `${sessionId}.jsonl`);\\n+}\\n+\\n+export function meaningfulEvents(lines: string): string[] {\\n+  const selected: string[] = [];\\n+  for (const line of lines.split('\\\\n')) {\\n+    if (!line.trim()) continue;\\n+    try {\\n+      const event = JSON.parse(line);\\n+      if (event.type === 'progress') {\\n+        selected.push(JSON.stringify(event));\\n+      } else if (event.type === 'assistant' || event.type === 'user') {\\n+        const blocks = event.message?.content;\\n+        if (Array.isArray(blocks) && blocks.some((b: { type?: string; is_error?: boolean }) =>\\n+          b.type === 'tool_use' || b.type === 'tool_result' || (b.type === 'text' && event.type === 'assistant') || b.is_error)) {\\n+          selected.push(JSON.stringify(event));\\n+        }\\n+      }\\n+    } catch { /* Incomplete or invalid transcript line: ignore. */ }\\n+  }\\n+  return selected;\\n+}\\n+\\n+export class JsonlWatcherService {\\n+  private watcher?: FSWatcher;\\n+  private timer?: NodeJS.Timeout;\\n+  private offset = 0;\\n+  private pending = '';\\n+  private buffer: string[] = [];\\n+  private stopped = false;\\n+  private reading = false;\\n+\\n+  constructor(private readonly file: string, private readonly onBatch:\"")
